const httpResp = $input.first().json;
// Original document data (preserved through Code: Check Existing Entry)
const originalItem = $('Code: Check Existing Entry').first().json;

const insertSuccess = !httpResp.error && (httpResp.statusCode === 200 || httpResp.statusCode === 201 || !httpResp.statusCode);

// Capture the new Weaviate UUID for the parent BankStatement (used in Phase B for BankTransaction objects)
let newWeaviateId = null;
try {
  const respBody = httpResp.body || httpResp;
  const data = (typeof respBody === 'string') ? JSON.parse(respBody) : respBody;
  newWeaviateId = data?.id || null;
} catch(e) {}

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  if (insertSuccess) {
    if (originalItem.file_hash) {
      await client.sRem('alice:dms:queued_files', originalItem.file_hash);
      await client.sAdd('alice:dms:processed', originalItem.file_hash);
      if (originalItem.file_path) {
        const oldHash = await client.hGet('alice:dms:path_to_hash', originalItem.file_path);
        if (oldHash && oldHash !== originalItem.file_hash) {
          await client.hDel('alice:dms:path_to_hash', originalItem.file_path);
          await client.sRem(`alice:dms:hash_to_paths:${oldHash}`, originalItem.file_path);
        }
        await client.hSet('alice:dms:path_to_hash', originalItem.file_path, originalItem.file_hash);
        await client.sAdd(`alice:dms:hash_to_paths:${originalItem.file_hash}`, originalItem.file_path);
      }
    }
    await client.hIncrBy('alice:dms:run:stats', 'processed', 1);
  } else {
    await client.hIncrBy('alice:dms:run:stats', 'failed', 1);
  }
} finally {
  await client.quit();
}

return [{ json: { ...originalItem, _weaviate_inserted: insertSuccess, _new_weaviate_id: newWeaviateId } }];

// PROJ-29 Phase B: BankTransaction chunk extraction + batch indexing
// Runs only when the parent document is a BankStatement that was just inserted.
// For all other doc types this node is a passthrough.
//
// Bug fixes:
//   BUG-3: Use GraphQL Get + DELETE-by-ID instead of delete-by-where (more reliable; body
//          on DELETE is dropped by some HTTP stacks).
//   BUG-13: Cascade-delete BankTransaction children for the OLD parent UUID when this is a
//          replace (same path, different hash) — prevents orphans.
//   BUG-4: Add 1× retry per chunk on Ollama failure / unparseable JSON.
//   BUG-5: Skip transactions with null transactionDate (do not pollute the collection).
//   BUG-6: Drop empty purpose so it is not embedded as an empty-string vector.
//   BUG-8: Emit _phase_b_failure flag so downstream MQTT nodes can publish a Phase B
//          summary to alice/dms/error on partial failure (mqtt module is not in
//          NODE_FUNCTION_ALLOW_EXTERNAL — published via dedicated n8n MQTT nodes).

const axios = require('axios');
const redis = require('redis');

const item = $input.first().json;
const WEAVIATE_URL = 'http://weaviate:8080';
const CHUNK_SIZE = 8000;
const OLLAMA_TIMEOUT_MS = 180000; // 3 min per chunk

// Passthrough for non-BankStatement or failed inserts
if (item._document_type !== 'BankStatement' || !item._weaviate_inserted || !item._new_weaviate_id) {
  return [{ json: item }];
}

const parentId = item._new_weaviate_id;
// BUG-13: capture OLD parent UUID if this was a replace (existing class was BankStatement)
const oldParentId = (item._existing_weaviate_class === 'BankStatement' && item._existing_weaviate_id && item._existing_weaviate_id !== parentId)
  ? item._existing_weaviate_id
  : null;
const plaintext = item.plaintext || '';
const extractedHeader = item._extracted || {};
const bankName = extractedHeader.bankName || null;
const accountIban = extractedHeader.iban || null;
const statementCurrency = extractedHeader.currency || 'EUR';
const now = new Date().toISOString();

let ollamaModel = 'qwen3.5:27b-q4_K_M';
try { ollamaModel = $env.OLLAMA_MODEL_DMS || 'qwen3:14b'; } catch(e) {}

function toISODate(val) {
  if (!val) return null;
  try {
    const d = new Date(val);
    if (isNaN(d.getTime())) return null;
    return d.toISOString();
  } catch(e) { return null; }
}
function toNum(val) {
  if (val === null || val === undefined || val === '') return null;
  const n = parseFloat(String(val).replace(',', '.'));
  return isNaN(n) ? null : Math.abs(n);
}
function normDirection(val) {
  if (!val) return null;
  const v = String(val).toLowerCase().trim();
  if (['credit', 'eingang', 'in', 'gutschrift', '+'].includes(v)) return 'credit';
  if (['debit', 'ausgang', 'out', 'lastschrift', 'belastung', '-'].includes(v)) return 'debit';
  return null;
}

// BUG-3 helper: resolve all BankTransaction children for a given parentStatementId via
// GraphQL Get (paged), then DELETE each by UUID. This is more reliable than delete-by-where
// because (a) HTTP DELETE bodies are dropped by some HTTP stacks, (b) Weaviate batch-delete
// API formats vary across versions, and (c) per-ID delete returns explicit per-object status.
// Returns { deleted, failed }.
async function cascadeDeleteChildren(pid) {
  let deleted = 0;
  let failed = 0;
  if (!pid) return { deleted, failed };
  // Sanitize: only allow UUID-shaped strings (defensive — pid comes from internal sources only)
  const safePid = String(pid).replace(/[^a-zA-Z0-9-]/g, '');
  if (!safePid || safePid !== pid) {
    console.warn(`[Phase B] cascadeDeleteChildren: invalid parent UUID '${pid}' — skipping cascade`);
    return { deleted, failed };
  }
  const PAGE = 100;
  // Loop until no more results returned
  while (true) {
    const gql = `{ Get { BankTransaction(where: { path: ["parentStatementId"], operator: Equal, valueText: "${safePid}" }, limit: ${PAGE}) { _additional { id } } } }`;
    let ids = [];
    try {
      const r = await axios.post(`${WEAVIATE_URL}/v1/graphql`, { query: gql }, {
        headers: { 'Content-Type': 'application/json' },
        timeout: 15000
      });
      const hits = r.data?.data?.Get?.BankTransaction || [];
      ids = hits.map(h => h?._additional?.id).filter(Boolean);
    } catch(e) {
      console.warn(`[Phase B] cascadeDeleteChildren GraphQL Get failed for parent ${safePid}: ${e.message}`);
      break;
    }
    if (ids.length === 0) break;
    for (const id of ids) {
      try {
        await axios.delete(`${WEAVIATE_URL}/v1/objects/BankTransaction/${id}`, { timeout: 10000 });
        deleted++;
      } catch(e) {
        // 404 means already deleted — not an error
        if (e.response?.status === 404) {
          deleted++;
        } else {
          failed++;
          console.warn(`[Phase B] cascadeDeleteChildren: delete failed for ${id}: ${e.message}`);
        }
      }
    }
    // If less than page size returned we are done
    if (ids.length < PAGE) break;
  }
  return { deleted, failed };
}

// 1a. BUG-13: Cascade-delete children of the OLD parent UUID on replace
let oldDeleted = 0;
if (oldParentId) {
  const r = await cascadeDeleteChildren(oldParentId);
  oldDeleted = r.deleted;
  console.log(`[Phase B] Cascade-deleted ${r.deleted} BankTransactions of replaced parent ${oldParentId} (${r.failed} failed)`);
}

// 1b. BUG-3: Delete any pre-existing children of the NEW parent UUID (idempotency for re-processing)
const { deleted: newDeleted } = await cascadeDeleteChildren(parentId);
if (newDeleted > 0) {
  console.log(`[Phase B] Deleted ${newDeleted} pre-existing BankTransactions for new parent ${parentId}`);
}

// 2. Split plaintext into chunks at newline boundaries
function splitChunks(text, maxLen) {
  if (!text) return [];
  if (text.length <= maxLen) return [text];
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + maxLen, text.length);
    if (end < text.length) {
      // Try to find the last newline within the window
      const lastNl = text.lastIndexOf('\n', end);
      if (lastNl > start + Math.floor(maxLen / 2)) {
        end = lastNl + 1;
      }
    }
    chunks.push(text.slice(start, end));
    start = end;
  }
  return chunks;
}

const chunks = splitChunks(plaintext, CHUNK_SIZE);
console.log(`[Phase B] BankStatement ${parentId}: ${chunks.length} chunk(s) of plaintext (${plaintext.length} chars)`);

// 3. Per-chunk Ollama call to extract a JSON array of transactions (with 1× retry, BUG-4)
const extractionPromptHeader = `You are a bank-statement transaction extractor. From the following text fragment of a bank statement, extract every individual booking line as a JSON array. Respond ONLY with a JSON object {"transactions": [...]} — no prose, no explanation.

Each element MUST be an object with these fields:
  "transactionDate":  "YYYY-MM-DD"  (booking date, required)
  "valueDate":        "YYYY-MM-DD"  (Wertstellung, optional, null if absent)
  "amount":           number         (always POSITIVE, sign goes into 'direction')
  "currency":         string         (e.g. "EUR")
  "direction":        "credit" or "debit"  (credit = Eingang/Gutschrift, debit = Ausgang/Lastschrift)
  "counterparty":     string         (sender name on credits, recipient name on debits)
  "purpose":          string         (Verwendungszweck / booking text; empty string if absent)
  "counterpartyIban": string or null (IBAN of the other side if present)
  "balanceAfter":     number or null (account balance after this booking if present)
  "rawText":          string         (the original booking line as-is)

IMPORTANT:
- Ignore lines that look like statement headers, totals, page footers, opening/closing balances.
- Ignore incomplete transactions at the very start or end of the fragment that look truncated.
- Dates must be ISO format YYYY-MM-DD. If only DD.MM. is present, use the year from context if obvious; otherwise null.
- Numbers must be plain JSON numbers (use "." as decimal separator, no thousands separators).
- If no transactions are visible in the fragment, return {"transactions": []}.

Text fragment:
`;

async function extractChunk(chunkText) {
  const ollamaResp = await axios.post('http://ollama-3090:11434/api/generate', {
    model: ollamaModel,
    prompt: extractionPromptHeader + chunkText,
    stream: false,
    format: 'json',
    options: { temperature: 0 }
  }, { timeout: OLLAMA_TIMEOUT_MS });
  const respText = ollamaResp.data?.response || '';
  const parsed = JSON.parse(respText); // throws if invalid JSON — caught by caller
  if (!Array.isArray(parsed.transactions)) throw new Error('response missing transactions array');
  return parsed.transactions;
}

let allTx = [];
let chunkRetries = 0;
let chunkFailures = 0;
for (let i = 0; i < chunks.length; i++) {
  const chunkText = chunks[i];
  let txs = null;
  try {
    txs = await extractChunk(chunkText);
  } catch(e1) {
    console.warn(`[Phase B] chunk ${i + 1}/${chunks.length} attempt 1 failed: ${e1.message} — retrying once`);
    chunkRetries++;
    try {
      txs = await extractChunk(chunkText);
    } catch(e2) {
      chunkFailures++;
      console.warn(`[Phase B] chunk ${i + 1}/${chunks.length} retry failed: ${e2.message} — dropping chunk`);
      continue;
    }
  }
  console.log(`[Phase B] chunk ${i + 1}/${chunks.length}: ${txs.length} transactions extracted`);
  allTx.push(...txs);
}

// 4. Deduplicate by (transactionDate, amount, counterparty)
const seen = new Set();
const dedup = [];
for (const tx of allTx) {
  const date = tx.transactionDate || '';
  const amount = tx.amount != null ? String(tx.amount) : '';
  const cp = (tx.counterparty || '').trim().toLowerCase();
  const key = `${date}|${amount}|${cp}`;
  if (seen.has(key)) continue;
  seen.add(key);
  dedup.push(tx);
}
console.log(`[Phase B] Deduplicated: ${allTx.length} -> ${dedup.length} transactions`);

// 5. Empty-list handling: log warning, do not fail. Downstream MQTT routing emits the
// summary based on _phase_b_failure flag (set below).
if (dedup.length === 0) {
  console.warn(`[Phase B] WARN: No transactions extracted from BankStatement ${parentId} (file=${item.file_path})`);
  return [{ json: {
    ...item,
    _transactions_indexed: 0,
    _transactions_failed: 0,
    _transactions_extracted: 0,
    _phase_b_chunk_failures: chunkFailures,
    _phase_b_chunk_retries: chunkRetries,
    _phase_b_chunks_total: chunks.length,
    _phase_b_skipped_null_date: 0,
    _phase_b_old_children_deleted: oldDeleted,
    // chunkFailures with zero extracted is a partial failure signal for MQTT routing
    _phase_b_failure: chunkFailures > 0
  } }];
}

// 6. Build BankTransaction objects + batch insert via Weaviate /v1/batch/objects
let skippedNullDate = 0;
const objects = [];
for (const tx of dedup) {
  const txDate = toISODate(tx.transactionDate);
  // BUG-5: skip transactions without a valid transactionDate (required field)
  if (!txDate) {
    skippedNullDate++;
    console.warn(`[Phase B] Skipping transaction with null transactionDate (parent=${parentId}): ${JSON.stringify({ amount: tx.amount, counterparty: tx.counterparty }).slice(0, 200)}`);
    continue;
  }
  const purposeStr = (tx.purpose || '').toString().trim();
  const props = {
    parentStatementId: parentId,
    transactionDate: txDate,
    valueDate: toISODate(tx.valueDate),
    amount: toNum(tx.amount),
    currency: tx.currency || statementCurrency,
    direction: normDirection(tx.direction),
    counterparty: (tx.counterparty || '').toString(),
    // BUG-6: drop purpose entirely when empty (avoids embedding an empty-string vector)
    purpose: purposeStr || null,
    counterpartyIban: tx.counterpartyIban || null,
    balanceAfter: toNum(tx.balanceAfter),
    bankName,
    accountIban,
    rawText: (tx.rawText || '').toString(),
    createdBy: 'alice-dms-processor',
    createdAt: now
  };
  // Drop null/undefined values — Weaviate does not accept null for typed fields
  const cleaned = Object.fromEntries(Object.entries(props).filter(([_, v]) => v !== null && v !== undefined));
  objects.push({ class: 'BankTransaction', properties: cleaned });
}
if (skippedNullDate > 0) {
  console.warn(`[Phase B] Skipped ${skippedNullDate} transactions with missing transactionDate`);
}

let successCount = 0;
let failCount = 0;
if (objects.length > 0) {
  try {
    const batchResp = await axios.post(`${WEAVIATE_URL}/v1/batch/objects`, {
      objects
    }, {
      headers: { 'Content-Type': 'application/json' },
      timeout: 60000
    });
    const results = Array.isArray(batchResp.data) ? batchResp.data : [];
    for (const r of results) {
      const errs = r?.result?.errors?.error;
      if (errs && errs.length) {
        failCount++;
        console.warn(`[Phase B] BankTransaction insert error: ${JSON.stringify(errs)}`);
      } else {
        successCount++;
      }
    }
    // Fallback: if results array missing, treat HTTP-200 as full success
    if (results.length === 0 && objects.length > 0) {
      successCount = objects.length;
    }
  } catch(e) {
    console.warn(`[Phase B] Weaviate batch insert failed: ${e.message}`);
    failCount = objects.length;
  }
}

// 7. Update Redis stats counter
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const rclient = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await rclient.connect();
try {
  if (successCount > 0) {
    await rclient.hIncrBy('alice:dms:run:stats', 'transactions_indexed', successCount);
  }
  if (chunkFailures > 0) {
    await rclient.hIncrBy('alice:dms:run:stats', 'phase_b_chunk_failures', chunkFailures);
  }
  if (chunkRetries > 0) {
    await rclient.hIncrBy('alice:dms:run:stats', 'phase_b_chunk_retries', chunkRetries);
  }
} finally {
  await rclient.quit();
}

// 8. BUG-8: Set partial/full-failure flag so downstream MQTT node can publish to alice/dms/error
const phaseBFailure = (failCount > 0) || (chunkFailures > 0) || (objects.length > 0 && successCount === 0);

console.log(`[Phase B] BankTransaction batch insert: ${successCount} ok, ${failCount} failed (parent=${parentId}, chunkFailures=${chunkFailures})`);
return [{ json: {
  ...item,
  _transactions_indexed: successCount,
  _transactions_failed: failCount,
  _transactions_extracted: dedup.length,
  _phase_b_chunk_failures: chunkFailures,
  _phase_b_chunk_retries: chunkRetries,
  _phase_b_chunks_total: chunks.length,
  _phase_b_skipped_null_date: skippedNullDate,
  _phase_b_old_children_deleted: oldDeleted,
  _phase_b_failure: phaseBFailure
} }];

const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  const items = await client.lRange('alice:dms:image', 0, -1);
  if (items.length === 0) {
    return [{ json: { _image_empty: true } }];
  }
  const results = [];
  for (const raw of items) {
    try {
      const parsed = JSON.parse(raw);
      results.push({ json: { ...parsed, _image_empty: false, _raw_json: raw } });
    } catch(e) {
      await client.lRem('alice:dms:image', 0, raw).catch(() => {});
    }
  }
  if (results.length === 0) {
    return [{ json: { _image_empty: true } }];
  }
  console.log('[Image Batch] Found ' + results.length + ' image items to process');
  return results;
} finally {
  await client.quit();
}

const redis = require('redis');
const axios = require('axios');
const item = $input.first().json;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  if (item._raw_json) {
    await client.lRem('alice:dms:image', 0, item._raw_json).catch(() => {});
  }
  const fileHash = item.file_hash;
  if (!fileHash) {
    return [{ json: { ...item, _image_action: 'skip' } }];
  }
  // Search Weaviate Image collection by file_hash
  const safeHash = fileHash.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\x00-\x1f]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
  const query = `{ Get { Image(where: { path: ["file_hash"], operator: Equal, valueText: "${safeHash}" }, limit: 1) { _additional { id } additionalPaths } } }`;
  let existingId = null;
  let existingPaths = [];
  try {
    const searchResp = await axios.post('http://weaviate:8080/v1/graphql', { query }, { headers: { 'Content-Type': 'application/json' }, timeout: 10000 });
    const results = searchResp.data?.data?.Get?.Image || [];
    if (results.length > 0) {
      existingId = results[0]._additional?.id;
      existingPaths = results[0].additionalPaths || [];
    }
  } catch(e) {
    console.log('[Image] Weaviate search error: ' + e.message);
  }
  if (existingId) {
    const filePath = item.file_path;
    if (filePath && !existingPaths.includes(filePath)) {
      try {
        await axios.patch(`http://weaviate:8080/v1/objects/Image/${existingId}`,
          { properties: { additionalPaths: [...existingPaths, filePath] } },
          { headers: { 'Content-Type': 'application/json' }, timeout: 10000 }
        );
      } catch(e) { console.log('[Image] additionalPaths patch error: ' + e.message); }
    }
    return [{ json: { ...item, _image_action: 'add_path', _image_existing_id: existingId } }];
  }
  // New image: build Weaviate properties
  const exif = item.exif || {};
  const geo = item.geocoding || {};
  const now = new Date().toISOString();
  function toISODate(val) { if (!val) return null; try { const d = new Date(val); return isNaN(d.getTime()) ? null : d.toISOString(); } catch(e) { return null; } }
  const props = {
    file_path: item.file_path || '',
    file_hash: fileHash,
    file_type: item.file_type || '',
    file_size: item.file_size || 0,
    detected_at: toISODate(item.detected_at) || now,
    extracted_at: toISODate(item.extracted_at) || now,
    extractor: item.extractor || 'dms-extractor-image',
    ai_description: (item.ai_description || '').slice(0, 50000),
    extraction_failed: item.extraction_failed || false,
    additionalPaths: []
  };
  if (exif.datetime) { const d = toISODate(exif.datetime); if (d) props.exif_datetime = d; }
  if (exif.latitude != null) props.latitude = parseFloat(exif.latitude);
  if (exif.longitude != null) props.longitude = parseFloat(exif.longitude);
  if (exif.altitude != null) props.altitude = parseFloat(exif.altitude);
  if (exif.camera_make) props.camera_make = String(exif.camera_make);
  if (exif.camera_model) props.camera_model = String(exif.camera_model);
  if (geo.country) props.country = String(geo.country);
  if (geo.country_code) props.country_code = String(geo.country_code);
  if (geo.city) props.city = String(geo.city);
  if (geo.district) props.district = String(geo.district);
  const cleanProps = Object.fromEntries(Object.entries(props).filter(([_, v]) => v !== null && v !== undefined));
  let newId = null;
  let insertOk = false;
  try {
    const insertResp = await axios.post('http://weaviate:8080/v1/objects', { class: 'Image', properties: cleanProps }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });
    newId = insertResp.data?.id;
    insertOk = !!newId;
  } catch(e) { console.log('[Image] Weaviate insert error: ' + e.message); }
  if (insertOk) {
    await client.sAdd('alice:dms:processed', fileHash).catch(() => {});
    await client.hIncrBy('alice:dms:run:stats', 'processed', 1).catch(() => {});
  } else {
    await client.hIncrBy('alice:dms:run:stats', 'failed', 1).catch(() => {});
  }
  return [{ json: { ...item, _image_action: insertOk ? 'new' : 'error', _new_weaviate_id: newId, _image_insert_ok: insertOk } }];
} catch(e) {
  console.log('[Image] Unhandled error: ' + e.message);
  return [{ json: { ...item, _image_action: 'error', _image_error: e.message } }];
} finally {
  try { await client.quit(); } catch(e) {}
}
